algorithm SumOfMultiplesOfThree
    define bound as integer;
    define i as integer;
    define total as integer;
    read bound;
    total <- 0;
    for i <- 0 to bound step 3 do
        total <- total + i;
    endFor
    write total;
endAlgorithm

